package com.example.starter.wb.enums;

/**
 * 舱单版本状态。
 */
public enum ManifestStatus {
    /** 预配 */
    PRELIMINARY,
    /** 值机 */
    CHECKIN,
    /** 装载确认 */
    LOADED,
    /** 双岗复核通过（舱单冻结） */
    REVIEWED,
    /** 放行关闭（终态） */
    CLOSED,
    /** 已被新版本替代 */
    SUPERSEDED
}

package com.example.starter.wb.enums;

/**
 * 业载类别。
 */
public enum LoadCategory {
    /** 旅客 */
    PASSENGER,
    /** 行李 */
    BAGGAGE,
    /** 货物 */
    CARGO,
    /** 邮件 */
    MAIL
}

package com.example.starter.wb.enums;

/**
 * 双岗复核岗位；两名不同岗位各签字一次，复核方生效。
 */
public enum ReviewRole {
    /** 配载平衡员 */
    LOAD_CONTROLLER,
    /** 飞行签派员 */
    FLIGHT_DISPATCHER
}

