package com.example.starter.wb.dto;

import java.math.BigDecimal;

/**
 * 业载明细录入项。
 *
 * @param category      业载类别：PASSENGER/BAGGAGE/CARGO/MAIL
 * @param stationCode   装载站位代码
 * @param pieces        人数或件数（旅客为人，其余为件；LMC 可为负）
 * @param unitWeightKg  单位重量，kg/人或 kg/件
 */
public record LoadItem(
        String category,
        String stationCode,
        int pieces,
        BigDecimal unitWeightKg
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;
import java.util.List;

/**
 * 预配舱单创建请求（首版）。
 */
public record CreateManifestRequest(
        @NotBlank String requestId,
        @NotNull Long flightId,
        @NotNull @PositiveOrZero BigDecimal fuelKg,
        @NotBlank String createdBy,
        @NotEmpty List<LoadItem> items
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.math.BigDecimal;
import java.util.List;

/**
 * 值机阶段业载更新请求：以全量明细重算舱单。
 */
public record CheckinRequest(
        @NotBlank String requestId,
        @NotEmpty List<LoadItem> items,
        BigDecimal fuelKg,
        @NotBlank String operator
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 阶段推进请求（装载确认等无业务字段的操作）。
 */
public record StageRequest(
        @NotBlank String requestId,
        @NotBlank String operator
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 最后一分钟修正（LMC）请求。
 * 旅客增量作用于旅客站位，货物增量作用于货运站位；燃油增量同步触发重心重算。
 */
public record LmcRequest(
        @NotBlank String requestId,
        int passengerDelta,
        @NotBlank String paxStationCode,
        @NotNull BigDecimal weightDeltaKg,
        @NotBlank String weightStationCode,
        @NotNull BigDecimal fuelDeltaKg,
        @NotBlank String operator
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 双岗复核签字请求。
 */
public record ReviewRequest(
        @NotBlank String requestId,
        @NotBlank String role,
        @NotBlank String reviewer
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 放行关闭请求。
 */
public record CloseRequest(
        @NotBlank String requestId,
        @NotBlank String closedBy
) {
}

package com.example.starter.wb.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 关闭后迟到的值机变化上报。
 */
public record LateCheckinRequest(
        @NotBlank String requestId,
        int passengerCount,
        @NotNull BigDecimal weightKg,
        String detail
) {
}

