package com.example.starter.wb.calc;

import java.math.BigDecimal;

/**
 * 计算用业载项：重量 = pieces * unitWeightKg，作用于给定力臂。
 */
public record CalcLoadItem(
        String category,
        String stationCode,
        int pieces,
        BigDecimal unitWeightKg,
        BigDecimal arm
) {
    public boolean isPassenger() {
        return "PASSENGER".equals(category);
    }

    public BigDecimal weightKg() {
        return unitWeightKg.multiply(BigDecimal.valueOf(pieces));
    }

    public BigDecimal moment() {
        return weightKg().multiply(arm);
    }
}

