/**
 * requestId 幂等包装：先查幂等表，同键同参回放首次结果，同键异参 409；
 * 业务成功后落首次结果快照。操作表上的唯一约束兜底并发同键。
 */
private ManifestResponse withIdempotency(String requestId, Object payload, int successStatus,
                                         java.util.function.Supplier<ManifestResponse> action) {
    String fp = fingerprint(requestId, payload);
    Optional<IdempotentRow> existing = repo.findIdempotent(requestId);
    if (existing.isPresent()) {
        IdempotentRow first = existing.get();
        if (!first.fingerprint().equals(fp)) {
            throw new ConflictException("requestId " + requestId + " 已用于不同业务参数（指纹不一致），拒绝产生新版本");
        }
        return replay(first);
    }
    ManifestResponse response;
    try {
        response = action.get();
    } catch (DuplicateKeyException dke) {
        // 并发同键：唯一约束决胜，转为回放或冲突。
        Optional<IdempotentRow> raced = repo.findIdempotent(requestId);
        if (raced.isPresent() && raced.get().fingerprint().equals(fp)) {
            return replay(raced.get());
        }
        throw new ConflictException("相同请求并发处理，唯一一笔生效，requestId=" + requestId);
    }
    IdempotentRow record = new IdempotentRow(requestId, fp, successStatus, safeJson(response),
            LocalDateTime.now(clock));
    try {
        repo.insertIdempotent(record);
    } catch (DuplicateKeyException e) {
        Optional<IdempotentRow> raced = repo.findIdempotent(requestId);
        if (raced.isPresent() && raced.get().fingerprint().equals(fp)) {
            return replay(raced.get());
        }
        throw new ConflictException("requestId " + requestId + " 已用于不同业务参数（指纹不一致）");
    }
    return response;
}

private ManifestResponse replay(IdempotentRow row) {
    try {
        return objectMapper.readValue(row.resultJson(), ManifestResponse.class);
    } catch (Exception e) {
        throw new IllegalStateException("回放首次结果失败", e);
    }
}

